const filtersBlock=document.querySelectorAll("[data-filters-block]");filtersBlock.length&&filtersBlock.forEach(t=>{t.querySelectorAll(".filters-aside__item").forEach(e=>{const s=e.querySelector(".filters-aside__toggle");e.classList.contains("is-open")&&s.classList.add("is-active"),s.addEventListener("click",()=>{e.classList.toggle("is-open"),s.classList.toggle("is-active")})})});
